export function defaultWsUrl(loc = globalThis.location) {
  if (!loc || !loc.host) return 'ws://localhost:3000/ws';
  // shell patch: ?server=<origin> redirects the socket only (web version on GitHub Pages:
  // assets from the CDN, WS straight to the room host)
  try {
    const srv = new URLSearchParams(loc.search || '').get('server');
    if (srv) {
      const u = new URL(/^https?:\/\//.test(srv) ? srv : `http://${srv}`);
      return `${u.protocol === 'https:' ? 'wss' : 'ws'}://${u.host}/ws`;
    }
  } catch (e) { /* fall through to the default */ }
  return `${loc.protocol === 'https:' ? 'wss' : 'ws'}://${loc.host}/ws`;
}

